   "id": "z32860f5c",
   "sez": "prima",
   "titolo": "Allarmi bomba in 3800 scuole, indaga l'Antiterrorismo",
   "orig": "Nuovi allarmi nelle scuole, un’altra giornata di caos. “Mail da Taiwan e Filippine”",
   "lead": "Un'ondata di falsi allarmi bomba ha colpito circa 3800 scuole italiane, causando l'evacuazione di 77 istituti. Le minacce sono arrivate via email da server localizzati a Taiwan e nelle Filippine, portando la firma di un fantomatico mittente denominato Antropov. Il governo ha invitato le scuole a non sospendere le lezioni, sottolineando la necessità di impedire che tali minacce blocchino i servizi pubblici essenziali. L'Antiterrorismo di Roma e Milano ha aperto un'indagine per identificare i responsabili di questa operazione coordinata, volta a creare caos nelle istituzioni scolastiche di tutto il Paese.",
   "more": [
    "In Italia, l'interruzione di pubblico servizio e il procurato allarme sono reati puniti severamente. L'utilizzo di server esteri e tecniche di anonimizzazione rende le indagini informatiche complesse, richiedendo la cooperazione internazionale tra polizie postali. Il coinvolgimento dell'Antiterrorismo evidenzia la serietà con cui le autorità affrontano azioni che minano la sicurezza e la regolarità della vita scolastica nazionale."
   ],
