   "id": "z3e2db0c2",
   "sez": "mondo",
   "titolo": "Scontro elettorale in Australia tra Laburisti e Verdi",
   "orig": "Victoria election 2026: Labor and Greens trade accusations of ‘dodgy deals’ as preferences squabble puts key seats on the line",
   "lead": "In vista delle elezioni nello Stato di Victoria del 2026, è scoppiato un acceso scontro politico tra il Partito Laburista e i Verdi riguardo alla gestione delle preferenze elettorali. I Verdi hanno accusato i Laburisti di aver stretto accordi poco trasparenti e hanno risposto escludendo il partito dalle loro indicazioni di voto in 15 collegi elettorali chiave. Questo conflitto interno alla sinistra potrebbe favorire le coalizioni di centro-destra, mettendo a rischio la tenuta di seggi fondamentali per la maggioranza uscente. Entrambe le fazioni si scambiano accuse di favorire indirettamente gli avversari politici. Lo riferisce The Guardian.",
   "more": [
    "Il sistema elettorale australiano si basa sul voto preferenziale, dove gli elettori indicano un ordine di gradimento per i candidati. Gli accordi tra i partiti su come indirizzare le seconde preferenze (le 'how-to-vote cards') sono decisivi per determinare l'esito finale nei collegi più contesi, influenzando direttamente la formazione dei governi statali e federali."
   ],
   "fonti": [
    {
     "n": "The Guardian",
     "p": "UK",
     "c": "Londra",
     "u": "https://www.theguardian.com/australia-news/2026/nov/13/victoria-state-election-2026-labor-greens-preference-deals-seats",
     "angolo": "",
     "atlas": "United Kingdom",
     "t": "2026-11-13T06:16+00:00"
    }
   ],
   "data": "13 nov",
