   "id": "zde7e5b75",
   "sez": "sport",
   "titolo": "Pat Cummins nega il coinvolgimento nello scandalo del 2018",
   "orig": "Australia captain Pat Cummins denies involvement in ‘Sandpapergate’ scandal",
   "lead": "Il capitano della nazionale australiana di cricket, Pat Cummins, ha smentito categoricamente le recenti affermazioni del compagno di squadra Usman Khawaja riguardo allo scandalo del 'Sandpapergate' del 2018. Cummins ha dichiarato che Khawaja ha torto nel sostenere che l'intera squadra fosse a conoscenza della manomissione della palla durante il match contro il Sudafrica. La polemica riaccende i riflettori su uno dei momenti più difficili dello sport australiano, con Cummins impegnato a difendere l'integrità del gruppo attuale rispetto alle pesanti sanzioni che colpirono i leader del team dell'epoca. Lo riferisce Al Jazeera.",
   "more": [
    "La manomissione della palla (ball-tampering) è considerata una violazione gravissima nel cricket, poiché altera la traiettoria del lancio. Lo scandalo del 2018 portò alla squalifica dei principali giocatori australiani e a una profonda crisi di reputazione per la federazione, i cui strascichi continuano a influenzare il dibattito sportivo nazionale."
   ],
