   "titolo": "Burkina Faso, scontro tra gruppi jihadisti rivali",
   "orig": "Burkina Faso’s rival armed groups turn on each other as state loses ground",
   "lead": "In Burkina Faso, i gruppi armati JNIM e ISIL hanno intensificato i combattimenti tra loro per ottenere il controllo delle zone in cui l'autorità dello Stato è ormai assente. Mentre le forze governative faticano a contenere l'estendersi del conflitto, le fazioni rivali si contendono l'egemonia territoriale, aggravando la crisi di sicurezza e umanitaria per la popolazione civile. La lotta fratricida tra le organizzazioni jihadiste sta trasformando il Paese in un teatro di violenze incontrollate, con lo Stato che perde progressivamente terreno nelle aree rurali e di confine. Lo riferisce Al Jazeera.",
   "more": [],
