   "id": "zb982ce71",
   "sez": "prima",
   "titolo": "Hegseth premia il soldato che lo aveva rimproverato ad Arlington",
   "orig": "Hegseth awards medal to war memorial guard who reprimanded him and group",
   "lead": "Il segretario alla Difesa degli Stati Uniti, Pete Hegseth, ha conferito una medaglia allo specialista Thomas Iglesias, la guardia che lo aveva richiamato per il suo comportamento inappropriato al Cimitero di Arlington. Iglesias aveva ordinato al gruppo di Hegseth di fare silenzio mentre parlavano e ridevano vicino alla Tomba del Milite Ignoto durante le celebrazioni del Veterans Day. Il gesto di Hegseth intende onorare l'integrità e la fermezza del soldato nel far rispettare le solenni regole di condotta del memoriale, nonostante la differenza di rango e ruolo istituzionale tra i due.",
   "more": [
    "Le guardie del 3° Reggimento di Fanteria, incaricate della sorveglianza della Tomba del Milite Ignoto, sono addestrate a mantenere un rigore assoluto. La loro autorità all'interno del perimetro del memoriale è totale, permettendo loro di intervenire contro chiunque disturbi la sacralità del luogo, a dimostrazione del valore che le istituzioni militari americane attribuiscono alla memoria dei caduti."
   ],
