   "id": "z924f96af",
   "sez": "prima",
   "titolo": "Gli Houthi colpiscono l'Arabia Saudita mentre l'ONU rinnova le sanzioni",
   "orig": "Yemen’s Houthis renew strikes on Saudi Arabia as UNSC extends sanctions",
   "lead": "I ribelli Houthi dello Yemen hanno lanciato nuovi attacchi con droni contro infrastrutture petrolifere e militari in Arabia Saudita, intercettati dalla coalizione guidata da Riad. L'offensiva è avvenuta in concomitanza con il voto all'unanimità del Consiglio di Sicurezza dell'ONU per estendere le sanzioni e le restrizioni di viaggio contro i leader del gruppo ribelle. Mentre il Pakistan ha chiesto la cessazione immediata delle ostilità, si sollevano timori sull'espansione del programma missilistico saudita. Gli attacchi minacciano la stabilità economica della regione e la fiducia degli investitori stranieri nei progetti di sviluppo sauditi.",
   "more": [
    "Il conflitto yemenita è una complessa crisi regionale che vede contrapposti i ribelli Houthi, sostenuti dall'Iran, e il governo yemenita appoggiato dall'Arabia Saudita. Gli attacchi transfrontalieri colpiscono spesso obiettivi civili e industriali sensibili, influenzando i mercati energetici globali e rendendo difficile il raggiungimento di una tregua duratura mediata dalle Nazioni Unite."
   ],
