   "id": "za80b7235",
   "sez": "prima",
   "titolo": "Meta disattiva i profili di Russell Brand dopo la condanna",
   "orig": "Russell Brand's social media accounts disabled by Meta",
   "lead": "Meta ha rimosso gli account Instagram e Facebook di Russell Brand in seguito alla condanna a 10 anni e mezzo di carcere inflitta all'ex comico britannico per aggressioni sessuali. La decisione dell'azienda segue la sentenza definitiva che ha posto fine alla carriera della star, accusata da diverse donne di gravi abusi commessi negli anni passati. Mentre nel Regno Unito si discute della sua caduta, Netflix si appresta a lanciare un documentario che ricostruisce i reati per cui è stato condannato. Brand ha inviato un ultimo messaggio tramite X, ringraziando Elon Musk per non aver censurato la sua voce.",
   "more": [
    "La condanna di Russell Brand segna il culmine di un caso che ha scosso l'opinione pubblica britannica, evidenziando il lato oscuro dell'industria dello spettacolo. Il provvedimento di Meta rientra nelle politiche di sicurezza delle piattaforme social, che prevedono la rimozione di profili appartenenti a individui condannati per reati sessuali gravi per prevenire ulteriori danni o strumentalizzazioni."
   ],
