   "sez": "prima",
   "titolo": "Russia, condannata a 12 anni l'avvocata Maria Bontsler",
   "orig": "Russian court jails rights lawyer for 12 years on treason charge",
   "lead": "Un tribunale russo ha condannato a 12 anni di carcere Maria Bontsler, nota avvocata russa impegnata nella difesa dei diritti umani, con l'accusa di alto tradimento. Secondo i procuratori, la donna avrebbe condiviso informazioni riservate sulla sicurezza con l'Ucraina, mentre la difesa ha sostenuto che tali dati non fossero segreti. Bontsler, 66 anni, è celebre per aver assistito imputati in numerosi processi politici complessi. Contemporaneamente, attivisti hanno denunciato la scoperta di un registro riservato delle autorità che elenca oltre 3000 persone, tra cui giornalisti e musicisti, sospettate di estremismo e sabotaggio.",
   "more": [
    "Il reato di alto tradimento in Russia è stato notevolmente ampliato per includere attività civili e legali considerate contrarie agli interessi nazionali. Questo processo si inserisce in un clima di crescente repressione del dissenso interno, dove le figure impegnate nella tutela dei diritti civili vengono sistematicamente prese di mira per limitare la loro capacità di agire e di informare l'opinione pubblica internazionale."
   ],
