   "id": "z9f8661a2",
   "sez": "economia",
   "titolo": "Lee Jae Myung annuncia riforme per il mercato azionario coreano",
   "orig": "(LEAD) Lee pledges capital market reform to address stock undervaluation",
   "lead": "Il presidente sudcoreano Lee Jae Myung ha promesso una profonda riforma del mercato dei capitali per risolvere il problema della cronica sottovalutazione delle azioni delle aziende nazionali. Lee ha indicato le acquisizioni ostili come un meccanismo fondamentale per normalizzare il mercato e ha invitato i funzionari a studiare misure che favoriscano la trasparenza e la competitività. L'obiettivo dichiarato è quello di attrarre nuovi investitori e colmare il divario di valore che penalizza le società della Corea del Sud rispetto ai principali concorrenti internazionali, stimolando così la crescita economica del Paese.",
   "more": [
    "Il cosiddetto 'Korea Discount' si riferisce alla tendenza delle azioni coreane a essere scambiate a prezzi inferiori rispetto a quelle di società simili in altri mercati globali. Le riforme proposte mirano a modernizzare la governance delle grandi imprese familiari (chaebol) e a rendere il mercato più attraente per i flussi di capitale esteri, garantendo maggiore tutela ai piccoli azionisti."
   ],
