   "sez": "salute",
   "titolo": "Nuova ondata di Ebola a Mambasa, strutture sanitarie in crisi",
   "orig": "Recrudescence des cas d’Ebola à Mambasa : les capacités de prise en charge sous pression",
   "lead": "Nel territorio di Mambasa, nella provincia dell'Ituri, si sta verificando una preoccupante recrudescenza di casi di Ebola con una media di venti nuovi pazienti segnalati ogni settimana. Il medico capo della zona ha lanciato un allarme sulla pressione insostenibile a cui sono sottoposte le strutture di cura dell'ospedale generale di riferimento, che faticano a gestire l'aumento dei contagi registrato negli ultimi venti giorni. La situazione sanitaria è aggravata dalla crisi umanitaria che colpisce anche altre aree della regione, rendendo difficile l'accesso alle cure di base per migliaia di famiglie sfollate a causa dei conflitti locali. Lo riferisce Radio Okapi.",
   "more": [
    "Il virus Ebola causa una febbre emorragica altamente letale ed è trasmesso attraverso il contatto con fluidi corporei infetti. La gestione delle epidemie in zone di conflitto come l'Ituri è resa complessa dalla difficoltà di tracciamento dei contatti e dalla mancanza di forniture mediche costanti, fattori che aumentano il rischio di diffusione incontrollata del virus tra la popolazione vulnerabile."
   ],
