   "id": "zdfa0f672",
   "sez": "musica",
   "titolo": "U2, esce il duetto postumo con Dolly Parton",
   "orig": "Hear U2’s Posthumous Dolly Parton Duet",
   "lead": "Gli U2 hanno pubblicato 'Torn', un brano che vede la collaborazione postuma della leggenda del country Dolly Parton, traccia di chiusura del loro nuovo album 'Carnaval de Luz'. Bono ha raccontato che la Parton, nonostante fosse già gravemente malata, ha insistito per alzarsi dal letto e completare quella che sarebbe stata la sua ultima registrazione vocale. L'album, il sedicesimo lavoro in studio della band irlandese, viene descritto come un ciclo narrativo unico che celebra la vita prima della rinuncia. Il progetto è stato anticipato dall'uscita a sorpresa di due EP che completano il concept artistico del gruppo.",
   "more": [
    "L'uscita di un duetto postumo rappresenta un momento di grande valore emotivo e artistico per la discografia mondiale. Gli U2, attivi da oltre quarant'anni, continuano a sperimentare collaborazioni tra generi diversi, unendo in questo caso il rock alternativo con l'eredità storica del country americano incarnata da Dolly Parton, una delle artiste più influenti della musica popolare del XX secolo."
   ],
