   "id": "zb2bdef78",
   "sez": "ambiente",
   "titolo": "Piccole isole: fondo per il clima alimentato dalle rimesse",
   "orig": "Small islands aim to use remittances in climate battle",
   "lead": "Un gruppo di piccoli stati insulari ha proposto la creazione di un fondo per la resilienza climatica finanziato attraverso una tassa sulle rimesse inviate dai propri cittadini residenti all'estero. L'obiettivo è generare risorse economiche permanenti per finanziare progetti che rendano queste nazioni meno vulnerabili agli effetti del cambiamento climatico, come l'innalzamento del livello dei mari. Questo modello innovativo punterebbe a utilizzare i proventi della diaspora invece di dipendere esclusivamente dagli aiuti internazionali allo sviluppo, garantendo una base finanziaria autonoma per la protezione del territorio. Lo riferisce RTÉ News.",
   "more": [
    "Le rimesse dei migranti costituiscono una parte fondamentale del prodotto interno lordo per molti paesi insulari in via di sviluppo. Tuttavia, l'implementazione di una tassa su questi flussi di denaro privato pone sfide legali e sociali significative, in quanto si tratta di fondi destinati al sostentamento delle famiglie, ma l'urgenza della crisi climatica spinge i governi a cercare soluzioni di finanziamento non convenzionali."
   ],
