   "id": "z17997d10",
   "sez": "manga",
   "titolo": "Restrizioni per i fan stranieri al Comic Market",
   "orig": "Comic Market: Ticketpay Service Restricts Access for International Users",
   "lead": "Il servizio di biglietteria Ticketpay ha introdotto nuove restrizioni che bloccano l'accesso agli utenti internazionali interessati a partecipare al Comic Market (Comiket) in Giappone. Lo staff dell'evento ha annunciato l'apertura di un'indagine per trovare canali di acquisto alternativi destinati ai visitatori d'oltreoceano, dopo le numerose segnalazioni di impossibilità di ottenere i titoli d'ingresso. Problematiche simili riguardanti l'accesso dei turisti stranieri a siti culturali e manifestazioni di massa sono state riportate anche in altre aree del Paese, dove si cerca di bilanciare la gestione dei flussi con la sicurezza informatica. Lo riferisce Anime News Network.",
   "more": [
    "Il Comic Market di Tokyo è la più grande fiera al mondo dedicata alle opere autoprodotte e attira migliaia di fan da ogni continente. Le restrizioni sui sistemi di pagamento e prenotazione giapponesi sono spesso dovute a normative interne rigorose sulla verifica dell'identità e sulla prevenzione del bagarinaggio, che però creano barriere d'accesso significative per il pubblico internazionale non residente."
   ],
