   "id": "zeeacb4b8",
   "sez": "organizzazioni",
   "titolo": "La Germania finanzia l'OMC con 500.000 euro",
   "orig": "Germany contributes EUR 500,000 to strengthen developing economies' trade capacity",
   "lead": "La Germania ha contribuito con 500.000 euro al Global Trust Fund dell'Organizzazione Mondiale del Commercio (OMC) per sostenere la capacità commerciale delle economie in via di sviluppo e dei paesi meno avanzati. L'accordo è stato firmato a Ginevra dall'ambasciatrice tedesca Carmen Heidecke e mira a favorire una partecipazione più attiva di queste nazioni al sistema commerciale multilaterale. Intanto, in Mozambico, la società di dragaggio EMODRAGA è stata sollecitata dal governo a potenziare le proprie capacità operative per garantire la navigabilità dei canali di accesso ai porti e favorire così gli scambi commerciali della regione. Lo riferisce Organizzazione mondiale del commercio (Omc).",
   "more": [
    "L'Organizzazione Mondiale del Commercio gestisce fondi fiduciari per fornire assistenza tecnica ai paesi più poveri, aiutandoli a comprendere e applicare le regole del commercio globale. Questi finanziamenti sono cruciali affinché tali nazioni possano negoziare accordi equi e sviluppare infrastrutture logistiche adeguate, riducendo le disparità economiche tra i membri dell'organizzazione."
   ],
