   "id": "z22f7d066",
   "sez": "spazio",
   "titolo": "Hubble cattura una galleria di lenti gravitazionali per la futura missione Roman",
   "orig": "NASA’s Hubble Offers Cosmic Sampler of Targets for Roman",
   "lead": "La NASA ha pubblicato una raccolta di immagini catturate dal telescopio spaziale Hubble che mostrano diversi esempi di lenti gravitazionali. Queste osservazioni documentano la varietà del fenomeno cosmico e servono a preparare il terreno per i futuri studi del telescopio spaziale Nancy Grace Roman. Lo studio di come la gravità devia la luce di galassie distanti permetterà agli astronomi di mappare la materia oscura e comprendere meglio l'espansione dell'universo. La missione Roman beneficerà dell'ampio inventario di obiettivi identificati dal suo predecessore per condurre analisi più dettagliate e sistematiche. Lo riferisce Nasa.",
   "more": [
    "Le lenti gravitazionali si verificano quando la massa di un oggetto celeste molto grande, come un ammasso di galassie, curva lo spazio-tempo deformando la luce proveniente da sorgenti retrostanti. Questo effetto agisce come una lente d'ingrandimento naturale, permettendo agli scienziati di osservare oggetti dell'universo primordiale che altrimenti sarebbero troppo deboli per essere rilevati dai telescopi attuali."
   ],
