   "id": "z5ff2160e",
   "sez": "ingegneria",
   "titolo": "I Kansas City Chiefs scelgono la joint venture Clark-AECOM per il nuovo stadio",
   "orig": "Kansas City Chiefs Tap Clark-AECOM JV for New Stadium",
   "lead": "I Kansas City Chiefs hanno selezionato la joint venture formata da Clark Construction e AECOM per la realizzazione del loro nuovo stadio, un progetto dal valore stimato di 3 miliardi di dollari. L'iniziativa fa parte di un più ampio piano di investimenti da 4,5 miliardi di dollari nello stato del Kansas, che include anche un centro di allenamento da 300 milioni e vari progetti adiacenti. Attualmente il team è impegnato nel trasformare il concetto iniziale di design in un progetto esecutivo, gestendo i permessi e la pianificazione del budget per la struttura da 70.000 posti.",
   "more": [
    "La progettazione di stadi moderni richiede un coordinamento complesso tra architettura sportiva e ingegneria civile per integrare flussi di spettatori, sicurezza e sostenibilità economica. Spesso questi impianti diventano il fulcro di riqualificazioni urbane, attirando investimenti in infrastrutture e servizi che trasformano l'area circostante in un polo di intrattenimento attivo durante tutto l'anno."
   ],
