   "id": "z674fcfd3",
   "sez": "italia",
   "titolo": "Posizioni economiche ATA, vertice al Ministero sulla liquidazione delle spettanze",
   "orig": "Posizioni economiche ATA, a che punto siamo? Ecco le ultime notizie. SPECIALE con Dal Pino (ANIEF) LIVE Venerdì 13 novembre alle 14:30",
   "lead": "Si è tenuta una nuova riunione presso il Ministero dell'Istruzione e del Merito riguardante le posizioni economiche del personale ATA. I rappresentanti ministeriali hanno discusso con i sindacati lo stato della liquidazione delle somme dovute ai lavoratori del settore amministrativo, tecnico e ausiliario della scuola. L'Anief, rappresentata da Dal Pino, ha annunciato uno speciale informativo per aggiornare i dipendenti sulle ultime novità riguardanti la gestione delle pratiche e le tempistiche dei pagamenti. L'incontro punta a risolvere le pendenze economiche attese da tempo dal personale scolastico. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Il personale ATA svolge funzioni fondamentali per il funzionamento delle scuole italiane, occupandosi di compiti amministrativi, custodia e manutenzione. Le posizioni economiche sono progressioni stipendiali legate all'anzianità o a incarichi specifici; la loro gestione burocratica e finanziaria richiede spesso complessi passaggi tra i ministeri dell'Istruzione e dell'Economia."
   ],
