   "id": "z5b6e2dc6",
   "sez": "sport",
   "titolo": "L'Italia batte la Francia 3-1 a San Siro e conquista il primato in Nations League",
   "orig": "Una grande Italia ribalta la Francia e ora è prima in Nations League. Mancini: 'C'è voglia di riscatto'",
   "lead": "L'Italia ha conquistato il primo posto nel girone di Nations League superando la Francia per 3-1 allo stadio San Siro di Milano. Dopo il gol iniziale dei transalpini segnato da Olise, gli azzurri guidati da Mancini hanno reagito con una doppietta di Pio Esposito e una rete di Frattesi. La vittoria è stata segnata anche dall'errore dal dischetto di Sebastiano Esposito, fratello di Pio, che ha fallito un rigore prima della rimonta decisiva. Nonostante l'iniziale vantaggio francese, la nazionale italiana ha mostrato carattere e grinta, infliggendo una sconfitta alla squadra avversaria.",
   "more": [
    "La Nations League è una competizione calcistica continentale che ha sostituito gran parte delle amichevoli internazionali, offrendo alle nazionali europee un torneo strutturato. Vincere il girone permette l'accesso alle fasi finali e garantisce una posizione di vantaggio nei sorteggi per le qualificazioni ai principali tornei mondiali ed europei."
   ],
