   "id": "zc8fc7e3a",
   "sez": "manga",
   "titolo": "Presentato il film pilota per il nuovo anime originale Orochi -Seventh Echoes-",
   "orig": "Blue Rights Company Unveils Pilot Film for Orochi -Seventh Echoes- Original Animated Feature",
   "lead": "La società Blue Rights ha svelato il film pilota per 'Orochi -Seventh Echoes-', un lungometraggio animato originale diretto da Takashi Nakamura. Nakamura, noto per il suo lavoro come direttore dell'animazione in Akira, è accreditato anche per il concetto originale, il design dei personaggi e la direzione artistica del progetto. La presentazione del cortometraggio pilota offre un primo sguardo allo stile estetico e alla visione creativa del film, che punta su una narrazione originale slegata da adattamenti esistenti. Lo riferisce Anime News Network.",
   "more": [
    "L'industria dell'animazione giapponese utilizza spesso i film pilota per presentare lo stile visivo e la qualità tecnica di un progetto ai potenziali investitori e al pubblico. Takashi Nakamura è una figura di spicco del settore, avendo contribuito alla definizione dell'estetica moderna degli anime attraverso opere seminali che hanno influenzato generazioni di artisti in tutto il mondo."
   ],
