   "id": "zd42326d8",
   "sez": "viaggi",
   "titolo": "Turisti cinesi affrontano la giungla per vedere il relitto dell'ammiraglio Yamamoto",
   "orig": "Tourists Brave a Muddy Jungle Trek to See a Famed World War II Wreck",
   "lead": "Un gruppo composto da sette turisti cinesi e alcuni giornalisti ha affrontato un faticoso percorso nella giungla, guidato da abitanti locali, per raggiungere i resti dell'aereo dell'ammiraglio Isoroku Yamamoto. I partecipanti hanno dovuto aprirsi un varco con i maceti tra la fitta vegetazione e attraversare numerosi corsi d'acqua per osservare il relitto abbattuto durante la Seconda guerra mondiale. L'escursione testimonia il persistente interesse storico per i siti legati al conflitto nel Pacifico, nonostante le estreme difficoltà logistiche e ambientali per accedere alla zona remota. Lo riferisce The New York Times.",
   "more": [
    "Isoroku Yamamoto fu il comandante della flotta giapponese durante la Seconda guerra mondiale e l'ideatore dell'attacco a Pearl Harbor. Il suo aereo fu abbattuto dalle forze statunitensi nel 1943 sopra le Isole Salomone; oggi il sito dello schianto è diventato una meta per appassionati di storia militare e turisti avventurosi."
   ],
