   "id": "zadd8ea8f",
   "sez": "ambiente",
   "titolo": "Allarme siccità in Kazakistan: estate record per il ghiacciaio Tuyuksu",
   "orig": "Scientists Warn of Water Risks as Tuyuksu Glacier Records Warmest Summer Since 1972",
   "lead": "Il ghiacciaio Tuyuksu in Kazakistan ha registrato l'estate più calda dall'inizio delle rilevazioni meteorologiche nel 1972, perdendo circa 5,6 milioni di metri cubi d'acqua. I ricercatori del Centro Glaciologico dell'UNESCO hanno lanciato l'allarme per la sicurezza idrica a lungo termine nel sud-est del Paese, evidenziando come lo scioglimento accelerato metta a rischio le riserve vitali per l'agricoltura e il consumo umano. L'aumento delle temperature stagionali sta trasformando rapidamente l'ecosistema montano della regione, con conseguenze potenzialmente critiche per l'economia e la vita delle popolazioni locali. Lo riferisce The Astana Times.",
   "more": [
    "I ghiacciai dell'Asia centrale rappresentano fondamentali riserve idriche che alimentano i principali fiumi della regione durante la stagione secca. Il loro ritiro accelerato a causa del riscaldamento globale minaccia l'equilibrio di ecosistemi fragili e può innescare conflitti regionali per l'accesso alle risorse idriche, essenziali per la produzione alimentare e idroelettrica."
   ],
