   "id": "z16d8f3d6",
   "sez": "cultura",
   "titolo": "Un nastro trasportatore per rendere l'arte accessibile a Brooklyn",
   "orig": "Finnegan Shannon installs conveyor belt for displaying art accessibly in Brooklyn",
   "lead": "L'artista Finnegan Shannon ha installato un nastro trasportatore presso il centro culturale Pioneer Works di Brooklyn per esporre opere d'arte in modo più accessibile. L'installazione, intitolata 'There's No Me Without You', nasce dalla volontà di creare uno spazio espositivo che risponda alle esigenze di chi ha difficoltà motorie o di stazionamento prolungato. Attraverso questo meccanismo, le opere sfilano davanti ai visitatori comodamente seduti, offrendo un commento critico sull'accessibilità nel mondo dell'arte e trasformando la fruizione estetica in un'esperienza inclusiva e rilassata. Lo riferisce Dezeen.",
   "more": [
    "L'accessibilità universale nel mondo della cultura non riguarda solo l'abbattimento di barriere architettoniche come i gradini, ma anche la progettazione di modalità di fruizione alternative. Iniziative come questa stimolano il dibattito su come gli spazi pubblici possano essere ripensati per includere persone con diverse abilità fisiche, garantendo a tutti lo stesso diritto di partecipazione."
   ],
