   "id": "z312579d6",
   "sez": "mondo",
   "titolo": "Rissa ad Abu Dhabi: Nurmagomedov schiaffeggia il campione UFC Dvalishvili",
   "orig": "Brawl Erupts After Russian MMA Fighter Nurmagomedov Slaps Georgian Merab Dvalishvili in Abu Dhabi",
   "lead": "Ad Abu Dhabi, durante un'intervista in un hotel, il lottatore russo Usman Nurmagomedov ha aggredito il georgiano Merab Dvalishvili con uno schiaffo. L'incidente ha scatenato una rissa che ha coinvolto anche il giovane lottatore Saba Lazishvili, intervenuto per difendere Dvalishvili mentre il gruppo del russo cercava di sovrastarli. Le autorità locali hanno interrogato i partecipanti e Nurmagomedov rischia accuse formali e la detenzione negli Emirati Arabi Uniti. Il presidente della UFC, Dana White, ha reagito duramente definendo l'accaduto un atto stupido che danneggia l'immagine dello sport professionistico.",
   "more": [
    "Le arti marziali miste (MMA) impongono agli atleti rigidi codici di condotta per preservare l'integrità dello sport. Comportamenti violenti al di fuori delle competizioni ufficiali possono portare a pesanti sanzioni disciplinari, sospensioni dalle federazioni internazionali e conseguenze legali, poiché gli atleti sono soggetti alle leggi locali sulla pubblica sicurezza."
   ],
