   "id": "z9e9f664d",
   "sez": "dibattito",
   "titolo": "Decreto Scuola, dibattito su assunzioni e sostegno: voto decisivo in Senato",
   "orig": "Decreto Scuola, assunzioni da GPS su posti residui (mini doppio canale): martedì 17 il voto decisivo. Approvate le prime novità su PEI, specializzazione sul sostegno, studenti e istituti tecnici",
   "lead": "Il Senato italiano è prossimo al voto decisivo sulla conversione del Decreto Scuola, che introduce nuove norme sulle assunzioni dei docenti dalle graduatorie GPS per i posti residui. Il provvedimento tocca temi sensibili come la specializzazione sul sostegno e l'aggiornamento dei Piani Educativi Individualizzati (PEI) per gli studenti con disabilità. Parallelamente, a Roma, si discute della gestione delle occupazioni scolastiche dopo le denunce dei genitori per l'impedimento dell'accesso agli alunni disabili. Mentre il governo procede con l'iter legislativo, le opposizioni e i sindacati monitorano le modifiche che interesseranno il personale precario e gli istituti tecnici. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Il sistema di reclutamento dei docenti in Italia è oggetto di frequenti interventi legislativi per ridurre il precariato e garantire la copertura delle cattedre. Il supporto agli studenti con disabilità, attraverso figure specializzate e piani personalizzati, rappresenta un pilastro del diritto allo studio, richiedendo procedure di formazione e assunzione specifiche che il governo cerca di snellire attraverso nuovi canali normativi nazionali."
   ],
