   "id": "zdce19373",
   "sez": "cucina",
   "titolo": "La storia sociale del Karoo attraverso le ricette di Sydda Essop",
   "orig": "BOOK EXCERPT: Remembering Sydda Essop, who turned recipes into a social history of the Karoo",
   "lead": "Un estratto del libro dedicato alla memoria di Sydda Essop celebra l'eredità gastronomica della regione del Karoo, in Sudafrica, attraverso una raccolta di ricette e racconti intimi. L'opera documenta come il cibo sia diventato uno strumento di storia sociale, testimoniando gli incontri culturali e l'ospitalità che caratterizzano questa vasta area semi-desertica. Le tradizioni culinarie locali vengono presentate non solo come preparazioni alimentari, ma come espressione dell'identità collettiva e della memoria storica delle diverse comunità che abitano il territorio. Lo riferisce Daily Maverick.",
   "more": [
    "La gastronomia regionale spesso racchiude le influenze di popolazioni indigene, coloni e migranti, diventando un archivio vivente delle trasformazioni di un territorio. Nel Karoo, la cucina è un elemento centrale della vita quotidiana e della conservazione delle radici culturali, riflettendo la capacità delle comunità di adattarsi a un ambiente naturale difficile."
   ],
