   "sez": "sport",
   "titolo": "I Washington Commanders superano i Giants con un finale al cardiopalma",
   "orig": "Washington Commanders keep their season alive with last-gasp win over New York Giants",
   "lead": "I Washington Commanders hanno mantenuto vive le loro speranze stagionali grazie a una vittoria per 24-21 contro i New York Giants. Il successo è arrivato nell'ultimo minuto di gioco grazie a un touchdown da 32 yard di Stefon Diggs, servito dal quarterback Jayden Daniels. Nonostante Daniels avesse lanciato i suoi primi due intercetti della stagione poco prima, è riuscito a guidare la rimonta decisiva nella partita di giovedì notte. Per Washington si è trattato di uno scontro fondamentale per restare in corsa nella propria divisione e riscattare le prestazioni altalenanti delle scorse settimane. Lo riferisce The Guardian.",
   "more": [
    "Il football americano professionistico (NFL) è strutturato su una stagione regolare breve dove ogni partita è decisiva per l'accesso ai playoff. Le sfide del giovedì sera sono spesso caratterizzate da alta intensità e visibilità nazionale, mettendo alla prova la resistenza fisica e mentale dei giocatori chiamati a giocare con meno giorni di riposo rispetto al solito."
   ],
