   "id": "z79fa0fea",
   "sez": "economia",
   "titolo": "Gli Stati Uniti gestiscono 12 miliardi di dollari dai proventi del petrolio venezuelano",
   "orig": "EE. UU. entregó a Venezuela 12 000 millones de dólares por venta de crudo",
   "lead": "Tra gennaio e settembre 2026, gli Stati Uniti hanno gestito oltre 12 miliardi di dollari derivanti dalla vendita di risorse naturali venezuelane, principalmente petrolio. Secondo un rapporto del Dipartimento di Stato, i fondi sono stati inseriti in un sistema di custodia per autorizzare l'uso delle entrate da parte del governo ad interim. Contemporaneamente, in Cile, il Gruppo CAP sta preparando la vendita di asset per 40 milioni di dollari per ridurre il debito aziendale dopo anni di perdite finanziarie.",
   "more": [
    "L'economia del Venezuela dipende fortemente dalle esportazioni di petrolio, ma sanzioni internazionali e instabilità politica hanno complicato l'accesso alle rendite energetiche. Gli Stati Uniti utilizzano meccanismi di custodia per garantire che i proventi non vengano utilizzati per scopi illeciti e per sostenere le autorità riconosciute a livello internazionale, cercando di stabilizzare la situazione economica e umanitaria nel Paese sudamericano."
   ],
