   "id": "zee0ff4a0",
   "sez": "economia",
   "titolo": "Nvidia sotto esame in Asia: riflettori accesi su società di Singapore e Malesia",
   "orig": "Nvidia case puts Singapore, Malaysia companies in spotlight",
   "lead": "Le autorità stanno indagando sui legami finanziari tra diverse società tecnologiche asiatiche a seguito dei controlli sui chip Nvidia. Documenti aziendali hanno rivelato una connessione tra Alibaba e Megaspeed attraverso le loro filiali in Singapore e Malesia. In particolare, la sussidiaria malese Speedmatrix ha impegnato attrezzature informatiche e proprietà intellettuale a favore di Apex Enterprise Solutions a Singapore. Queste operazioni sono finite al centro dell'attenzione in un momento di crescente scrutinio internazionale sulle catene di approvvigionamento di componenti critici per l'intelligenza artificiale.",
   "more": [
    "L'industria dei semiconduttori è oggi soggetta a rigide restrizioni commerciali globali, specialmente per i prodotti ad alte prestazioni utilizzati nell'intelligenza artificiale. Singapore e la Malesia fungono da snodi logistici e produttivi cruciali, rendendo le loro aziende particolarmente esposte alle indagini sulla conformità delle esportazioni. La trasparenza finanziaria in questi mercati è diventata una priorità per le autorità di regolamentazione internazionali e per le grandi aziende tecnologiche."
   ],
