   "id": "z789fd36b",
   "sez": "dibattito",
   "titolo": "Il governo italiano valuta modifiche al Superbonus per garantire la stabilità dei conti",
   "orig": "Superbonus, modifiche già in cantiere. Giorgetti: “Sono asburgico, i conti devono reggere”",
   "lead": "In Italia si discute di possibili modifiche alla manovra economica riguardo al Superbonus. Il ministro dell'Economia Giancarlo Giorgetti si è detto aperto a correzioni sulla norma che prevede di spalmare le compensazioni dei crediti d'imposta in dieci anni, a condizione che la stabilità finanziaria non venga compromessa. Secondo il ministro, i conti devono reggere e i \"muri portanti\" della legge di bilancio non possono essere rimossi. La discussione nasce dopo le critiche sollevate dalla Banca d'Italia e dall'Ufficio Parlamentare di Bilancio su temi quali sanità e pensioni.",
   "more": [
    "Il Superbonus è una misura introdotta per incentivare l'efficientamento energetico degli edifici, ma il suo elevato impatto sul debito pubblico ha spinto il governo a cercare soluzioni per mitigarne i costi. Il dibattito attuale vede contrapposte la necessità di onorare gli impegni con le imprese e i cittadini e l'urgenza di rispettare i parametri di bilancio europei. Le istituzioni finanziarie vigilano affinché la gestione di questi crediti non sottragga risorse a settori vitali come il welfare."
   ],
