   "id": "z42610616",
   "sez": "mondo",
   "titolo": "Morozov: “Il microchip decide la supremazia, è il nuovo petrolio”",
   "orig": "Morozov: “Il microchip è il nuovo petrolio, decide la supremazia”",
   "lead": "Il sociologo dei nuovi media Evgeny Morozov ha analizzato la caduta di Jensen Huang, sostenendo che i microchip rappresentino oggi ciò che il petrolio è stato nel secolo scorso: il fattore determinante per la supremazia mondiale. Secondo Morozov, Huang sarebbe stato rimosso per la violazione delle regole interne all'azienda piuttosto che per le sole accuse di spionaggio. Questo evento sottolinea come il controllo della tecnologia dei processori sia diventato un pilastro fondamentale del potere geopolitico ed economico contemporaneo. Lo riferisce la Repubblica.",
   "more": [
    "L'attuale competizione tecnologica tra potenze globali si gioca sulla capacità di progettare e produrre semiconduttori sempre più potenti. Questa sfida definisce non solo il mercato dell'elettronica, ma anche le capacità militari e lo sviluppo dell'intelligenza artificiale. Esperti di sociologia e tecnologia osservano come le grandi aziende del settore siano diventate attori politici a tutti gli effetti, soggette a pressioni governative senza precedenti."
   ],
