   "id": "z55447168",
   "sez": "mondo",
   "titolo": "L'industria della difesa in Lettonia registra una crescita significativa",
   "orig": "Defence industry in Latvia has expanded",
   "lead": "Circa 240 aziende operano attualmente nel settore della difesa in Lettonia, spinto da una crescente domanda di sicurezza e innovazione tecnologica. Le imprese lettoni stanno sviluppando droni, sensori, sistemi di comunicazione e soluzioni di cybersicurezza, beneficiando di un supporto finanziario più accessibile. Questa espansione è guidata anche dallo sviluppo di tecnologie autonome e sistemi di navigazione avanzati. La crescita del comparto mira a rafforzare la sicurezza nazionale e a promuovere lo sviluppo economico attraverso l'industria tecnologica avanzata. Lo riferisce LSM.",
   "more": [
    "A seguito dei mutamenti del panorama geopolitico in Europa orientale, molti Stati membri della NATO hanno incrementato gli investimenti nell'industria bellica e tecnologica. La Lettonia sta puntando sulla produzione interna di sistemi di sorveglianza e droni per ridurre la dipendenza dalle importazioni estere. Questo processo favorisce la nascita di un ecosistema di startup tecnologiche che collaborano strettamente con le forze armate e le istituzioni europee per la difesa."
   ],
