   "id": "z9b13214f",
   "sez": "prima",
   "titolo": "Tragedia a Brooklyn: crolla un edificio, otto morti tra cui due bambini",
   "orig": "Casualties continue to rise after Brooklyn building collapses",
   "lead": "A Brooklyn, New York, il crollo di un edificio residenziale di tre piani situato accanto a un cantiere edile ha provocato la morte di otto persone, inclusi due bambini, e il ferimento di altre diciotto. I primi soccorritori hanno interrotto le operazioni di salvataggio dopo aver confermato che non ci sono più vittime tra le macerie. Gli investigatori stanno ora esaminando le procedure di scavo e i sistemi di monitoraggio del cantiere adiacente, mentre si ipotizza che la pioggia torrenziale possa aver contribuito al cedimento strutturale.",
   "more": [
    "Il crollo di edifici durante i lavori di costruzione è spesso causato da scavi troppo profondi che compromettono la stabilità delle fondamenta delle strutture vicine. Negli Stati Uniti, rigorosi codici edilizi impongono l'uso di puntellamenti e monitoraggi costanti in contesti urbani densi. Le autorità locali sono responsabili della verifica della sicurezza dei cantieri, ma la velocità dello sviluppo edilizio può talvolta portare a gravi negligenze fatali per i residenti."
   ],
