   "id": "z6b434842",
   "sez": "mondo",
   "titolo": "Trump ordina a Vance di interrompere i colloqui con l'Iran",
   "orig": "Trump rimette in riga Vance: “Non serve un accordo con l’Iran”",
   "lead": "Il presidente eletto Donald Trump ha ordinato al suo vice JD Vance di cessare ogni negoziazione con l'Iran, affermando che gli Stati Uniti non necessitano di un nuovo accordo con Teheran. Trump ha esortato Vance a concentrarsi invece sulle indagini riguardanti presunti crimini commessi dai democratici e sulle frodi interne. Questa direttiva arriva mentre il Qatar continua la sua mediazione diplomatica e in Israele cresce la tensione politica tra Eisenkot e Netanyahu. Trump sposta così l'attenzione dalle questioni estere alle priorità di politica domestica. Lo riferisce la Repubblica.",
   "more": [
    "La politica estera statunitense nei confronti dell'Iran è stata spesso caratterizzata da forti oscillazioni tra tentativi di diplomazia e sanzioni severe. Un cambio di priorità verso le indagini interne riflette una strategia di isolazionismo parziale, dove le tensioni mediorientali vengono messe in secondo piano rispetto al consolidamento del potere nazionale. Questa posizione potrebbe influenzare gli equilibri di sicurezza globale e il ruolo degli Stati Uniti come mediatore internazionale."
   ],
