   "id": "zf968263f",
   "sez": "mondo",
   "titolo": "Qualificazioni CAN 2027: la Guinea batte l’Eritrea e rilancia le sue speranze",
   "orig": "Eliminatoires CAN 2027 : la Guinée bat l’Érythrée et se repositionne dans le groupe D",
   "lead": "Nella terza giornata delle eliminatorie per la Coppa d'Africa 2027, la nazionale della Guinea ha superato l'Eritrea con il punteggio di 2-1 allo stadio 28-Settembre di Conakry. Nonostante l'assenza della stella Guirassy e una preparazione travagliata, il Syli National è riuscito a ottenere tre punti fondamentali per rientrare in corsa nel gruppo D. Parallelamente, il Camerun ha confermato il suo dominio nel girone G battendo la Namibia, con il tecnico David Pagou che ha schierato una formazione giovane e determinata.",
   "more": [
    "La Coppa d'Africa (CAN) è la competizione calcistica più prestigiosa del continente e le qualificazioni rappresentano un momento cruciale per le federazioni nazionali. Raggiungere la fase finale garantisce visibilità internazionale ai giocatori e importanti introiti commerciali. Per nazioni come la Guinea, il calcio è anche un potente strumento di coesione sociale e orgoglio nazionale, specialmente quando si ottengono vittorie decisive davanti al proprio pubblico."
   ],
