   "id": "ze1e7139e",
   "sez": "mondo",
   "titolo": "Sicurezza nucleare in Corea del Sud e nuovi insediamenti in Kazakistan",
   "orig": "IAEA Sees Commitment to Operational Safety at Unit 2 of Kori Nuclear Power Plant in Republic of Korea",
   "lead": "L'Agenzia internazionale per l'energia atomica (Aiea) ha riscontrato un forte impegno per la sicurezza operativa nella centrale nucleare di Kori, in Corea del Sud. Contemporaneamente, il Kazakistan ha annunciato la costruzione di un nuovo insediamento per 33.000 residenti vicino alla futura centrale nucleare di Balkhash. In Sud Sudan, il sindaco di Juba ha avviato un'ispezione rigorosa degli impianti idrici locali per garantirne la sicurezza e ha stabilito una scadenza a dicembre per risolvere il problema dell'abbandono indiscriminato dei rifiuti nella capitale. Lo riferisce l'Aiea.",
   "more": [
    "L'energia nucleare richiede standard di sicurezza elevatissimi e una supervisione internazionale costante per prevenire incidenti. Mentre alcune nazioni potenziano i propri impianti esistenti, altre come il Kazakistan stanno pianificando nuove infrastrutture per rispondere alla crescente domanda energetica. Al contempo, nei paesi in via di sviluppo, la gestione dei servizi essenziali come l'acqua potabile e i rifiuti rimane una sfida amministrativa prioritaria per la salute pubblica."
   ],
