   "id": "z160e4ad9",
   "sez": "mondo",
   "titolo": "Anniversario del massacro di Santa Cruz a Dili e sfide ambientali in Bolivia",
   "orig": "Tinan 35 Masakre Santa Cruz: La’o Hamutuk Ezije Verdade, Justisa no Hapara Impunidade",
   "lead": "A Timor Est è stato commemorato il 35° anniversario del massacro di Santa Cruz del 1991, con rinnovate richieste di giustizia e verità per i crimini commessi durante l'occupazione indonesiana. Nello stesso tempo, nella città di Santa Cruz in Bolivia, gli ingegneri hanno avvertito che la deforestazione sta mettendo a rischio la sicurezza del centro urbano. Sul fronte sanitario e legale boliviano, sono stati segnalati oltre 400 nuovi casi annui di cancro alla prostata e si sono registrate le dimissioni di Irma Villavicencio dalla presidenza del tribunale dipartimentale locale.",
   "more": [
    "Il massacro di Santa Cruz nel 1991 fu un momento di svolta per l'indipendenza di Timor Est, grazie alla diffusione globale di immagini che documentavano la violenta repressione. In Bolivia, la regione di Santa Cruz è un motore economico che soffre per la rapida espansione agricola e urbana, che causa problemi ambientali critici come le inondazioni. La stabilità delle istituzioni giudiziarie è fondamentale per gestire queste tensioni tra sviluppo e conservazione."
   ],
