   "id": "z570b46c9",
   "sez": "mondo",
   "titolo": "Giubileo d'oro per le istituzioni educative in Bhutan e in India",
   "orig": "Motithang Higher Secondary School concludes Golden Jubilee celebrations",
   "lead": "La Motithang Higher Secondary School di Thimphu, in Bhutan, ha concluso le celebrazioni per i suoi 50 anni di attività alla presenza della Regina Madre Tshering Yangdoen Wangchuck. L'evento ha premiato il contributo della scuola all'istruzione nazionale. Contemporaneamente, in India, il primo ministro Narendra Modi ha inaugurato il giubileo d'oro del centro Prashanti Kutiram e ha partecipato alle celebrazioni per il centenario di H.V. Sheshadri. Modi ha inoltre avviato nuovi progetti universitari tramite collegamento video, sottolineando l'importanza della formazione e della tradizione nello sviluppo del Paese.",
   "more": [
    "Il Bhutan pone un'attenzione straordinaria all'istruzione come pilastro della sua filosofia di Felicità Interna Lorda, cercando di bilanciare modernità e cultura tradizionale. In India, le celebrazioni di istituzioni storiche servono a rafforzare l'identità nazionale e a promuovere l'eccellenza accademica in un sistema scolastico in rapida espansione. Entrambi i paesi vedono nelle scuole e nelle università il motore principale per la costruzione della società futura e del progresso economico."
   ],
