   "id": "z66665aab",
   "sez": "mondo",
   "titolo": "Guerra alle droghe e agli alcolici illeciti in Kenya e Sud Sudan",
   "orig": "Kirinyaga church leaders declare war on drugs, illicit alcohol",
   "lead": "In Kenya, i leader delle chiese di Kirinyaga hanno dichiarato guerra al traffico di droga e alla vendita di alcolici illegali, chiedendo alle autorità di smantellare le bische clandestine e le reti di distribuzione. Nello stesso tempo, il commissario della contea di Yirol West nel Sud Sudan ha imposto un divieto totale sulla vendita e il consumo di droghe illecite, incluse marijuana e metanfetamine, per contrastare l'aumento degli abusi nella città. Entrambi gli interventi mirano a proteggere la salute pubblica e a ridurre la criminalità legata alle dipendenze nelle comunità locali. Lo riferisce Citizen Digital.",
   "more": [
    "L'abuso di alcol prodotto illegalmente e di sostanze stupefacenti è una piaga sociale in diverse regioni africane, dove la mancanza di controlli sanitari rende questi prodotti estremamente tossici. I leader religiosi e locali giocano un ruolo fondamentale nella prevenzione, cercando di sopperire alla carenza di strutture di riabilitazione. Le autorità intensificano i divieti per limitare il degrado sociale e garantire la sicurezza dei giovani, i più colpiti da questi fenomeni."
   ],
