   "id": "z7600f143",
   "sez": "sport",
   "titolo": "Klopp chiede tempo per ricostruire la nazionale tedesca",
   "orig": "Klopp asks for time in Germany rebuild",
   "lead": "L'allenatore Jurgen Klopp, subentrato a Julian Nagelsmann dopo l'eliminazione della Germania contro il Paraguay nella Coppa del Mondo, ha chiesto tempo per completare il processo di ricostruzione della squadra. Klopp ha respinto le voci secondo cui la nazionale mancherebbe di talento, sottolineando invece la necessità di un percorso di crescita dopo i risultati deludenti degli ultimi grandi tornei internazionali. Il tecnico dei quattro volte campioni del mondo ha ribadito l'importanza di un lavoro graduale per ritrovare la competitività e lo spirito necessari per tornare ai vertici del calcio mondiale. Lo riferisce Citizen Digital.",
   "more": [
    "La nazionale di calcio della Germania sta attraversando uno dei periodi più difficili della sua storia recente, con eliminazioni precoci nei campionati mondiali ed europei. Jurgen Klopp è stato scelto per la sua vasta esperienza internazionale e la capacità di motivare i giocatori, cercando di integrare nuovi giovani talenti in un sistema tattico rinnovato. La pressione per ottenere risultati immediati è alta in un Paese dove il calcio è lo sport nazionale per eccellenza."
   ],
