   "id": "z9a57ba9b",
   "sez": "mondo",
   "titolo": "La Cina consegna agli USA i resti dei piloti americani della Seconda Guerra Mondiale",
   "orig": "China hands over remains of US pilots who aided wartime resistance",
   "lead": "Le autorità militari cinesi hanno consegnato agli Stati Uniti i resti di alcuni piloti americani che supportarono la resistenza della Cina durante la Seconda Guerra Mondiale. I resti sono stati recentemente rinvenuti lungo la rotta aerea 'Hump', un vitale corridoio di rifornimento sull'Himalaya utilizzato nel conflitto contro il Giappone.",
   "more": [
    "La rotta 'The Hump' collegava l'India alla Cina sorvolando le vette dell'Himalaya, ed era cruciale per trasportare forniture militari alle forze cinesi dopo l'occupazione giapponese delle vie terrestri. Il gesto simbolico riflette una rara cooperazione umanitaria e militare tra Pechino e Washington legata alla memoria storica comune."
   ],
