   "id": "zc576c258",
   "sez": "mondo",
   "titolo": "Il Messico blocca una nuova carovana di migranti verso gli Stati Uniti",
   "orig": "México impide paso a nueva caravana migratoria hacia EE.UU.",
   "lead": "Le autorità messicane, tra cui Guardia Nazionale e servizi migratori, hanno bloccato martedì il passaggio di una carovana composta da circa cento migranti centroamericani diretti verso il confine con gli Stati Uniti. L'operazione avviene in un clima di forte tensione politica dopo l'esito elettorale statunitense. Lo riferisce Confidencial.",
   "more": [
    "Il Messico affronta da anni una pressione migratoria crescente, agendo come cuscinetto per i flussi provenienti dal Centro America verso il confine statunitense. Le politiche di contenimento sono spesso influenzate dai rapporti diplomatici con Washington e dalla gestione della sicurezza interna lungo le principali rotte migratorie terrestri."
   ],
