   "titolo": "Cuba, le case di cambio statali offrono un tasso sul dollaro superiore al mercato nero",
   "orig": "Por primera vez, las Cadeca dan un mejor precio que la calle para el dólar",
   "lead": "A Cuba, le case di cambio statali Cadeca hanno iniziato a offrire un tasso di acquisto per il dollaro superiore a quello del mercato informale, un evento senza precedenti recenti. Mentre i centri ufficiali scambiano a 917 pesos, il mercato nero si è attestato a 915. Lo riferisce 14ymedio.",
   "more": [
    "L'economia cubana sta attraversando una grave crisi inflattiva, con il valore del peso in costante oscillazione rispetto alle valute straniere. Questa mossa delle autorità monetarie punta a drenare valuta pregiata dal mercato nero verso le casse statali, cercando di stabilizzare una situazione finanziaria estremamente fragile."
   ],
