   "titolo": "Cuba, Justicia 11J denuncia repressioni contro i familiari dei prigionieri politici",
   "orig": "Justicia 11J pide a la Federación de Mujeres que denuncie la represión contra familiares de presos políticos",
   "lead": "L'organizzazione Justicia 11J ha chiesto alla Federazione delle Donne Cubane di denunciare gli abusi subiti dai familiari dei prigionieri politici durante le visite carcerarie. Le accuse includono denudamenti forzati e minacce sulla custodia dei figli, in un quadro di crescente repressione del regime. Lo riferisce 14ymedio.",
   "more": [
    "La situazione dei diritti umani a Cuba è sotto esame internazionale dal luglio 2021, quando proteste di massa portarono a centinaia di arresti. Le organizzazioni indipendenti monitorano costantemente le condizioni dei detenuti e le pressioni psicologiche esercitate sulle loro famiglie per scoraggiare ogni forma di attivismo politico."
   ],
